import heapq
import itertools
from collections import defaultdict


def shortest_path(edges, start, end):
    graph = defaultdict(list)

    # Validate weights and build the graph
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Edge weights must be non-negative")
        graph[from_node].append((to_node, weight))

    if start == end:
        return (0, [start])

    distances = {start: 0}
    previous = {}
    counter = itertools.count()
    queue = [(0, next(counter), start)]

    while queue:
        current_distance, _, node = heapq.heappop(queue)

        if current_distance != distances.get(node):
            continue

        if node == end:
            break

        for neighbor, weight in graph[node]:
            new_distance = current_distance + weight

            if new_distance < distances.get(neighbor, float("inf")):
                distances[neighbor] = new_distance
                previous[neighbor] = node
                heapq.heappush(
                    queue,
                    (new_distance, next(counter), neighbor)
                )

    if end not in distances:
        return (None, None)

    path = []
    node = end

    while node != start:
        path.append(node)
        node = previous[node]

    path.append(start)
    path.reverse()

    return (distances[end], path)
